fn update(scene: &mut GameScene<'_>, time: &FrameTime) {
    let tick = time.fixed_tick as i32;
    if scene.counter_value("reacted") == 1 {
        return;
    }
    // `go_tick` is the tick the signal shows; a false start moves it.
    let go = scene.counter_or("go_tick", 120);
    let pressed = scene.pressed("react");
    if tick < go {
        if pressed {
            scene.add_to_counter("false_starts", 1);
            scene.set_counter("go_tick", tick + 120);
        }
        return;
    }
    scene.set_counter("ready", 1);
    scene.set_hud("Message", |hud| hud.text = "Go!".into());
    if pressed {
        scene.set_counter("reacted", 1);
        scene.set_counter("reaction_ms", (tick - go) * 1000 / 60);
        scene.set_hud("Message", |hud| hud.text = "{reaction_ms} ms".into());
    }
}
